    if bary is None:
        for j in range(W):
            col=[I[i][j] for i in range(H) if I[i][j]!=0]
            if len(set(col))>=3: bary=j; btype='v'; break
    seq=[I[bary][j] for j in range(W)] if btype=='h' else [I[j][bary] for j in range(H)]
    seq=[c for c in seq if c!=0]
    def cnt(c):
        if btype=='h': return sum(1 for i in range(H) for j in range(W) if I[i][j]==c and i!=bary)
        return sum(1 for i in range(H) for j in range(W) if I[i][j]==c and j!=bary)
    best=max(seq,key=lambda c:cnt(c))
