from collections import deque
def solve(I):
    H,W=len(I),len(I[0])
    seen=[[False]*W for _ in range(H)]; comps=[]
    for i in range(H):
        for j in range(W):
            if I[i][j]!=0 and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; cl=[]
                while q:
                    a,b=q.popleft(); cl.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and I[x][y]!=0 and not seen[x][y]:
                                seen[x][y]=True; q.append((x,y))
                comps.append(cl)
    tmpl=max(comps,key=len)
    tc=I[tmpl[0][0]][tmpl[0][1]]
    rs=[r for r,_ in tmpl]; cs=[c for _,c in tmpl]
    tr0,tr1=min(rs),max(rs); tl0,tl1=min(cs),max(cs)
    hgt=tr1-tr0+1; wdg=tl1-tl0+1
    geom=frozenset((r-tr0,c-tl0) for r,c in tmpl)
    btype=None; seq=None
    # palette bar: run of distinct nonzero colors >=3 that does NOT contain template color
    for i in range(H):
        nz=[j for j,x in enumerate(I[i]) if x!=0]
        if len(nz)>=3 and len(set(I[i][j] for j in nz))==len(nz) and tc not in (set(I[i][j] for j in nz)):
            cand=tuple(I[i][j] for j in nz)
            if seq is None or len(cand)>len(seq): seq=cand; btype='h'
    if seq is None:
        for j in range(W):
            col=[I[i][j] for i in range(H) if I[i][j]!=0]
            if len(col)>=3 and len(set(col))==len(col) and tc not in set(col):
                cand=tuple(col)
                if seq is None or len(cand)>len(seq): seq=cand; btype='v'
    assert seq is not None
    tidx=list(seq).index(tc) if tc in seq else -1
    out=[[0]*W for _ in range(H)]
    def paint(r0,c0,col):
        for rr in range(hgt):
            for cc in range(wdg):
                if (rr,cc) in geom:
                    nr=r0+rr; nc=c0+cc
                    if 0<=nr<H and 0<=nc<W: out[nr][nc]=col
    paint(tr0,tl0,tc)  # template first
    C=tl0; R=tr0
    if btype=='v':
        for k in range(tidx-1,-1,-1):
            R-=hgt; paint(R,C,seq[k])
        for k in range(tidx+1,len(seq)):
            R+=hgt; paint(R,C,seq[k])
    else:
        for k in range(tidx-1,-1,-1):
            C-=wdg; paint(R,C,seq[k])
        for k in range(tidx+1,len(seq)):
            C+=wdg; paint(R,C,seq[k])
    return out

